import React from 'react';
import './Realisations.css';

const gallery = [
  {
    src: 'https://images.unsplash.com/photo-1599209909601-3b5a7303a4b3',
    title: 'Bureaux',
    caption: 'Entretien régulier'
  },
  {
    src: 'https://images.unsplash.com/photo-1581578017420-2f6d8e7d4e9a',
    title: 'Cuisine professionnelle',
    caption: 'Remise en état'
  },
  {
    src: 'https://images.unsplash.com/photo-1531297484001-80022131f5a1',
    title: 'Open-space',
    caption: 'Nettoyage après travaux'
  },
  {
    src: 'https://images.unsplash.com/photo-1524758870432-af9fe0edf0df',
    title: 'Accueil / Hall',
    caption: 'Mise au propre quotidienne'
  },
  {
    src: 'https://images.unsplash.com/photo-1497366754035-f200968a6e72',
    title: 'Postes de travail',
    caption: 'Dépoussiérage et désinfection'
  },
  {
    src: 'https://images.unsplash.com/photo-1497366811353-6870744d04b2',
    title: 'Salle de réunion',
    caption: 'Préparation avant rendez-vous'
  }
];

export default function Realisations() {
  return (
    <section className="page real-page">
      <div className="card real-intro">
        <h2>Nos réalisations</h2>
        <p className="muted real-lead">
          Un aperçu de différents types d’interventions&nbsp;: bureaux, commerces, espaces communs,
          fin de chantier, remise en état. Vous pourrez ensuite remplacer ces visuels par vos photos
          avant / après.
        </p>
        <div className="real-tags">
          <span className="real-tag">Bureaux</span>
          <span className="real-tag">Commerces</span>
          <span className="real-tag">Copropriétés</span>
          <span className="real-tag">Fin de chantier</span>
          <span className="real-tag">Locations courte durée</span>
        </div>
      </div>

      <div className="card real-gallery-card">
        <div className="real-gallery">
          {gallery.map((item, i) => (
            <figure className="real-item" key={i}>
              <div className="real-image-wrap">
                <img
                  src={`${item.src}?auto=format&fit=crop&w=900&q=60`}
                  alt={`Réalisation +Propre – ${item.title}`}
                />
                <div className="real-overlay">
                  <div className="real-overlay-inner">
                    <span className="real-overlay-title">{item.title}</span>
                    <span className="real-overlay-caption">{item.caption}</span>
                  </div>
                </div>
              </div>
            </figure>
          ))}
        </div>
      </div>
    </section>
  );
}
